<script setup lang="ts">
import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{state,refreshMine,refreshPublic}from'../store';import{api,run}from'../api';import type{Activity}from'../types';import Icon from'../components/Icon.vue';import ActivityCard from'../components/ActivityCard.vue';import{activityState,date,activityImage}from'../utils'
const route=useRoute(),router=useRouter(),query=ref(''),category=ref('全部活动'),period=ref('即将开始'),selected=ref<Activity|null>(null),busy=ref(false),day=ref(String(route.query.day||''))
const filtered=computed(()=>state.activities.filter(a=>(category.value==='全部活动'||a.category===category.value)&&(!query.value||[a.title,a.clubName,a.location].join('').includes(query.value))&&(period.value==='全部记录'||(period.value==='已结束'?new Date(a.endsAt).getTime()<Date.now():new Date(a.endsAt).getTime()>=Date.now()))&&(!day.value||new Date(a.startsAt).toLocaleDateString('sv-SE')===day.value)))
const registered=computed(()=>state.mine.registrations.some(r=>r.activity.id===selected.value?.id))
watch(()=>route.query.activity,id=>{if(id)selected.value=state.activities.find(a=>a.id===Number(id))||null},{immediate:true})
watch(selected,a=>{if(!a&&route.query.activity)router.replace('/activities')})
async function register(){if(!state.user){selected.value=null;router.push({path:'/login',query:{redirect:route.fullPath}});return}busy.value=true;await run(async()=>{await api(`/activities/${selected.value!.id}/registrations`,'POST');await Promise.all([refreshMine(),refreshPublic()]);selected.value=null},'报名成功，期待现场见到你');busy.value=false}
</script>
<template><div class="page-content"><div class="page-heading"><div><div class="eyebrow">征途活动 · 训练 · 骑行 · 交流</div><h1>骑行活动<span class="greeting-dot">.</span></h1><p>查看活动安排，在线报名，签到后留下你的征途记录。</p></div><router-link to="/center?tab=activities" class="outline-link"><Icon name="ticket" :size="17"/>我的活动记录<Icon name="arrowup" :size="16"/></router-link></div><div class="info-box"><router-link to="/suggestions">活动建议 · 向管理员申请集体骑行活动 →</router-link></div><div class="filter-bar"><div class="filter-tabs"><button v-for="c in ['全部活动',...new Set(state.activities.map(a=>a.category))]" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><el-input v-model="query" placeholder="搜索活动或主办社团" clearable class="list-search"><template #prefix><Icon name="search" :size="16"/></template></el-input></div><div class="activity-toolbar"><el-radio-group v-model="period"><el-radio-button value="即将开始"/><el-radio-button value="已结束"/><el-radio-button value="全部记录"/></el-radio-group><el-date-picker v-model="day" type="date" value-format="YYYY-MM-DD" placeholder="按日期筛选" clearable/><span class="muted small">共 {{filtered.length}} 场活动</span></div><div class="activity-grid listing-activities"><ActivityCard v-for="a in filtered" :key="a.id" :activity="a" @select="selected=$event"/></div><el-empty v-if="!filtered.length" description="当前没有符合条件的活动，正式安排由俱乐部管理员发布"/></div>
<el-dialog :model-value="!!selected" @update:model-value="(v:boolean)=>{if(!v)selected=null}" :title="selected?.title" width="min(720px, 94vw)"><template v-if="selected"><img class="activity-detail-image" :src="activityImage(selected)" alt="骑行活动氛围"><div class="detail-title-row"><el-tag type="success">{{selected.category}}</el-tag><el-tag type="info">{{activityState(selected)}}</el-tag></div><p class="detail-description">{{selected.description}}</p><div class="detail-facts"><span><Icon name="compass"/>{{selected.clubName}}</span><span><Icon name="pin"/>{{selected.location}}</span><span><Icon name="calendar"/>{{date(selected.startsAt,true)}} — {{date(selected.endsAt,true)}}</span><span><Icon name="clock"/>报名截止：{{date(selected.registrationDeadline,true)}}</span><span><Icon name="users"/>已报名 {{selected.registrationCount}} / {{selected.capacity}} 人</span></div><div class="info-box">报名成功后，可在成员中心查看活动记录。签到需在活动现场获取签到码。</div></template><template #footer><el-button @click="selected=null">关闭</el-button><el-button v-if="registered" type="primary" @click="selected=null;router.push('/center?tab=activities')">已报名 · 查看我的活动</el-button><el-button v-else type="primary" :loading="busy" :disabled="!selected?.canRegister" @click="register">{{selected?.canRegister?(state.user?'立即报名':'登录后报名'):selected?activityState(selected):'报名已关闭'}}</el-button></template></el-dialog></template>
